import csv
import sys
from io import StringIO

# Read the cached file
with open('/home/ubuntu/smasurekar/hermes-agent-smasurekar/hermes-runs/20260907-234403__dsqa90__auto-skill/queries/deepsearchqa-0813/hermes_home/cache/web/ourworldindata.org-1592b3d234.md', 'r') as f:
    content = f.read()

# Parse CSV
lines = content.strip().split('\n')
reader = csv.reader(lines)
header = next(reader)  # Entity, Code, Year, Population, female (% of total population)

# Collect data by country
countries = {}
for row in reader:
    if len(row) < 4:
        continue
    entity, code, year_str, value_str = row[0], row[1], row[2], row[3]
    try:
        year = int(year_str)
        value = float(value_str)
    except:
        continue
    if code not in countries:
        countries[code] = {'name': entity, 'data': {}}
    countries[code]['data'][year] = value

# Find countries with female % < 45% in 2000
countries_under_45_2000 = []
for code, info in countries.items():
    if 2000 in info['data'] and info['data'][2000] < 45:
        countries_under_45_2000.append((code, info['name'], info['data'][2000]))

print(f"Countries with female % < 45% in 2000: {len(countries_under_45_2000)}")
for code, name, val in sorted(countries_under_45_2000, key=lambda x: x[2]):
    print(f"  {name} ({code}): {val:.4f}%")

# For each, calculate average 2020-2023
results = []
for code, name, val_2000 in countries_under_45_2000:
    data = countries[code]['data']
    values_2020_2023 = []
    for year in [2020, 2021, 2022, 2023]:
        if year in data:
            values_2020_2023.append(data[year])
    if len(values_2020_2023) == 4:
        avg = sum(values_2020_2023) / 4
        results.append((code, name, val_2000, avg, values_2020_2023))

# Sort by average 2020-2023 descending
results.sort(key=lambda x: x[3], reverse=True)

print("\nCountries with female % < 45% in 2000, sorted by 2020-2023 average:")
for code, name, val_2000, avg, vals in results:
    print(f"  {name} ({code}): 2000={val_2000:.4f}%, 2020-2023 avg={avg:.4f}%, yearly={vals}")

if results:
    best = results[0]
    print(f"\n*** ANSWER: {best[1]} ({best[0]}) had the highest average at {best[3]:.4f}% ***")
